mapper.select:
SELECT ppe.id, ppe.patient_id, pep.prescription_name, pt.name as patient_name, pt.gender, TIMESTAMPDIFF(YEAR, pt.birth_date, CURDATE()) as age, pt.birth_date, pt.medical_record_no as medical_record_number, pt.disease_type, pt.enrollment_institution, ppe.execution_institution, ppe.prescription_status, ppe.prescribing_doctor, ppe.created_time FROM patient_prescribed_exercise ppe LEFT JOIN patient_exercise_prescription pep ON ppe.exercise_prescription_id = pep.id LEFT JOIN patient pt ON ppe.patient_id = pt.id
AND ppe.execution_institution IS NOT NULL AND ppe.execution_institution != ''
AND pt.disease_type = #{query.diseaseType}
AND ppe.prescription_status = #{query.prescriptionStatus}
AND pt.enrollment_institution = #{query.enrollmentInstitution}
AND ppe.execution_institution = #{query.executionInstitution}
AND ( pt.name LIKE CONCAT('%', #{query.searchKeyword}, '%') OR pt.medical_record_no LIKE CONCAT('%', #{query.searchKeyword}, '%') )
ORDER BY ppe.created_time DESC
